from typing import List

class Solution:
    def anagramMappings(self, nums1: List[int], nums2: List[int]) -> List[int]:
        pos = {}
        for idx, val in enumerate(nums2):
            if val not in pos:
                pos[val] = []
            pos[val].append(idx)
        return [pos[val].pop() for val in nums1]

class Solution {
public:
    vector<int> anagramMappings(vector<int>& nums1, vector<int>& nums2) {
        unordered_map<int, vector<int>> pos;
        for (int i = 0; i < (int)nums2.size(); i++) {
            pos[nums2[i]].push_back(i);
        }
        vector<int> res;
        for (int x : nums1) {
            res.push_back(pos[x].back());
            pos[x].pop_back();
        }
        return res;
    }
};

class Solution {
    public int[] anagramMappings(int[] nums1, int[] nums2) {
        Map<Integer, List<Integer>> pos = new HashMap<>();
        for (int i = 0; i < nums2.length; i++) {
            pos.computeIfAbsent(nums2[i], k -> new ArrayList<>()).add(i);
        }
        int[] res = new int[nums1.length];
        for (int i = 0; i < nums1.length; i++) {
            List<Integer> list = pos.get(nums1[i]);
            res[i] = list.remove(list.size() - 1);
        }
        return res;
    }
}

var anagramMappings = function(nums1, nums2) {
    const pos = new Map();
    for (let i = 0; i < nums2.length; i++) {
        if (!pos.has(nums2[i])) pos.set(nums2[i], []);
        pos.get(nums2[i]).push(i);
    }
    return nums1.map(x => pos.get(x).pop());
};
